static void ui_event_BrightnessChange(lv_event_t * e)
{
    lv_event_code_t event_code = lv_event_get_code(e);
    
    // 1. WICHTIG: Stoppt JEDE Geste auf dem Slider sofort,
    // damit der Screen dahinter keine Wischtag-Aktion ausführt!
    if(event_code == LV_EVENT_GESTURE) {
        lv_event_stop_bubbling(e);
        return;
    }

    if(event_code == LV_EVENT_VALUE_CHANGED) {
        uint8_t brightness = (uint8_t)((lv_slider_get_value(lv_event_get_target(e)) * 255U) / 100U);
        lcd_set_brightness(brightness);
    }
}

